Pattern regionWords = Pattern.compile('[A-Z]+');
Matcher regionReplace = regionWords.matcher('aa ABC bb DEF cc');
regionReplace.region(3, 10);
System.assertEquals('aa x bb x cc', regionReplace.replaceAll('x'));

